insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-001',1,'语文','字音字形','单选题','基础','下列加点字注音完全正确的一项是（　）','{"A":"静谧（mì）　哺育（pǔ）　惟妙惟肖（xiào）","B":"矜持（jīn）　粗糙（zào）　吹毛求疵（cī）","C":"狭隘（ài）　绚丽（xuàn）　迥乎不同（jiǒng）","D":"庇护（pì）　广袤（mào）　坦荡如砥（dǐ）"}'::jsonb,'C','','A项“哺”读bǔ；B项“糙”读cāo；D项“庇”读bì。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-002',2,'语文','字音字形','单选题','基础','下列词语中没有错别字的一项是（　）','{"A":"闲熟　嶙峋　重峦叠嶂","B":"狼藉　蹒跚　因地制宜","C":"锁屑　滞留　诚惶诚恐","D":"躁热　推崇　自出心裁"}'::jsonb,'B','','A项“娴熟”；C项“琐屑”；D项“燥热”。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-003',3,'语文','词语运用','单选题','基础','依次填入下列句子横线处的词语，最恰当的一项是（　）读书，不仅能______我们的精神世界，还能______我们的品德修养，______我们的人生格局。','{"A":"充实　提升　拓宽","B":"充满　提高　扩展","C":"充实　提高　扩展","D":"充满　提升　拓宽"}'::jsonb,'A','','固定搭配：充实精神、提升修养、拓宽格局。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-004',4,'语文','成语运用','单选题','基础','下列句子中加点成语使用不恰当的一项是（　）','{"A":"他的演讲慷慨激昂，抑扬顿挫，赢得了阵阵掌声。","B":"面对困难，我们要迎难而上，不能轻言放弃。","C":"同学们井然有序地进入考场，遵守考试纪律。","D":"他上课经常迟到，老师批评多次依然我行我素，值得表扬。"}'::jsonb,'D','','“我行我素”是贬义词，与“值得表扬”矛盾。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-005',5,'语文','病句辨析','单选题','基础','下列句子没有语病的一项是（　）','{"A":"通过这次研学活动，使同学们增长了见识。","B":"能否坚持锻炼，是拥有健康体魄的重要条件。","C":"我们要养成认真书写、规范答题的良好习惯。","D":"他大约二十岁左右，正是青春奋斗的年纪。"}'::jsonb,'C','','A项缺主语；B项两面对一面；D项“大约”与“左右”重复。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-006',6,'语文','标点符号','单选题','基础','下列句子标点符号使用正确的一项是（　）','{"A":"我不知道今天会不会下雨？但我还是带了伞。","B":"参加活动的有：工人、农民、教师、医生、和学生。","C":"“吹面不寒杨柳风，”不错的，像母亲的手。","D":"南昌，一座红色之城、英雄之城、活力之城。"}'::jsonb,'D','','A项陈述句用逗号；B项删去“和”前顿号；C项引号内逗号应放在引号外。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-007',7,'语文','修辞手法','单选题','基础','下列句子所用修辞手法判断错误的一项是（　）','{"A":"那河畔的金柳，是夕阳中的新娘。（比喻）","B":"小草偷偷地从土里钻出来。（拟人）","C":"飞流直下三千尺，疑是银河落九天。（夸张）","D":"他长得很像他的爸爸。（比喻）"}'::jsonb,'D','','同类比较不是比喻。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-008',8,'语文','文学常识','单选题','基础','下列文学常识表述正确的一项是（　）','{"A":"《论语》是道家经典著作。","B":"李白被称为“诗圣”。","C":"《背影》的作者是朱自清。","D":"苏轼是婉约派词人代表。"}'::jsonb,'C','','《论语》是儒家经典；李白是诗仙；苏轼是豪放派词人。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-009',9,'语文','语句衔接','单选题','基础','下列句子语序排列最恰当的一项是（　）①学会感恩，是人生的必修课　②感恩父母，感恩师长，感恩朋友　③让感恩成为一种习惯　④心怀感恩，世界才会更温暖','{"A":"①②④③","B":"①④②③","C":"③①②④","D":"②①③④"}'::jsonb,'A','','总起—对象—意义—倡议。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-010',10,'语文','文言文翻译','单选题','基础','下列文言句子翻译正确的一项是：“见贤思齐焉”（　）','{"A":"看见贤人就想和他看齐","B":"看见贤人就一起思考","C":"看见贤人就想超过他","D":"看见贤人就互相学习"}'::jsonb,'A','','“齐”意为看齐。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-011',11,'语文','语言表达','单选题','基础','下列句子中，表达得体的一项是（　）','{"A":"我刚到府上拜访，您就外出了，真是不巧。","B":"你的拙作我已经拜读，写得非常不错。","C":"我一定会鼎力相助，帮你解决这个问题。","D":"这是我的点心意，请你务必笑纳。"}'::jsonb,'D','','A项逻辑与场景不匹配；B项“拙作”是谦辞；C项“鼎力相助”是敬辞；D项表达得体。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-012',12,'语文','词语感情色彩','单选题','基础','下列词语中，全是褒义词的一组是（　）','{"A":"勤奋　善良　自私　勇敢","B":"坚强　乐观　奉献　高尚","C":"傲慢　谦逊　淳朴　真诚","D":"马虎　果断　坚定　正直"}'::jsonb,'B','','A项“自私”、C项“傲慢”、D项“马虎”是贬义词。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-013',13,'语文','关联词','单选题','基础','下列句子中，关联词使用正确的一项是（　）','{"A":"只要努力学习，才能取得好成绩。","B":"虽然明天下雨，但是我们要按时到校。","C":"他不仅学习好，而且品德高尚。","D":"因为天气很冷，所以他坚持晨跑。"}'::jsonb,'C','','A项应为“只要……就……”；B项应为“即使……也……”；D项应为“虽然……但是……”。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-014',14,'语文','古诗词理解','单选题','基础','下列诗句中，描写夏季的一项是（　）','{"A":"小荷才露尖尖角，早有蜻蜓立上头。","B":"停车坐爱枫林晚，霜叶红于二月花。","C":"忽如一夜春风来，千树万树梨花开。","D":"天街小雨润如酥，草色遥看近却无。"}'::jsonb,'A','','A项写夏季；B项写秋季；C项写冬季；D项写春季。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-015',15,'语文','作家作品','单选题','基础','下列作家与作品对应错误的一项是（　）','{"A":"鲁迅——《朝花夕拾》","B":"茅盾——《子夜》","C":"巴金——《茶馆》","D":"曹禺——《雷雨》"}'::jsonb,'C','','《茶馆》的作者是老舍，巴金代表作有《家》《春》《秋》。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
