insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-017',17,'语文','字音字形','单选题','基础','下列词语中没有错别字的一项是（　）','{"A":"沉缅　馈赠　中流砥柱","B":"取缔　襁褓　断壁残垣","C":"狡辨　堕落　销声匿迹","D":"寒喧　部署　脍炙人口"}'::jsonb,'B','','A项“沉湎”；C项“狡辩”；D项“寒暄”。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-018',18,'语文','词语运用','单选题','基础','依次填入下列句子横线处的词语，最恰当的一项是（　）读书______智慧，学习______能力，奋斗______未来。','{"A":"启迪　提升　铸就","B":"启发　提高　铸造","C":"启迪　提高　铸造","D":"启发　提升　铸就"}'::jsonb,'A','','固定搭配：启迪智慧、提升能力、铸就未来。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-019',19,'语文','成语运用','单选题','基础','下列句子中加点成语使用恰当的一项是（　）','{"A":"同学们经常向老师请教，这种不耻下问的精神值得提倡。","B":"井冈山革命遗址的故事让人叹为观止。","C":"他操作计算机非常熟练，已经达到了无所不为的程度。","D":"面对困难，我们要锲而不舍，勇往直前。"}'::jsonb,'D','','A项“不耻下问”不用于学生问老师；B项“叹为观止”多形容景物、技艺；C项“无所不为”是贬义词。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-020',20,'语文','病句辨析','单选题','基础','下列句子没有语病的一项是（　）','{"A":"为了防止这类事故不再发生，我们必须加强安全教育。","B":"经过不懈努力，使他的成绩有了很大提高。","C":"能否具备顽强的毅力，是一个人事业成功的重要条件。","D":"我们要继承和发扬中华民族的优良传统。"}'::jsonb,'D','','A项否定不当；B项缺主语；C项两面对一面。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-021',21,'语文','标点符号','单选题','基础','下列句子标点符号使用有误的一项是（　）','{"A":"今天去呢，还是明天去呢？我实在拿不定主意。","B":"老师要求：一、认真审题；二、规范书写；三、仔细检查。","C":"“鞠躬尽瘁，死而后已”，正好准确地描述了他的一生。","D":"西湖之美在于精致而大气，它宛如江南女子尽显柔美情怀，更像热血男儿展现宽阔胸怀。"}'::jsonb,'D','','D项是并列分句，第二个逗号应改为分号。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-022',22,'语文','修辞手法','单选题','基础','下列句子没有使用修辞手法的一项是（　）','{"A":"他像往常一样走进教室。","B":"乱花渐欲迷人眼，浅草才能没马蹄。","C":"飞流直下三千尺，疑是银河落九天。","D":"油蛉在这里低唱，蟋蟀们在这里弹琴。"}'::jsonb,'A','','A项只是比较陈述；B项对偶；C项夸张、比喻；D项拟人。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-023',23,'语文','文学常识','单选题','基础','下列文学常识表述有误的一项是（　）','{"A":"《红楼梦》是我国古代小说的巅峰之作，作者曹雪芹。","B":"苏轼是宋代豪放派词人，号东坡居士。","C":"《战国策》是我国第一部编年体通史。","D":"朱自清是现代散文家、诗人，著有《背影》。"}'::jsonb,'C','','我国第一部编年体通史是《资治通鉴》，《战国策》是国别体史书。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-024',24,'语文','语句衔接','单选题','基础','下列句子语序排列最合理的一项是（　）①那该是多么有意义的生活　②我们要多读书，读好书　③让书香伴随成长　④在阅读中收获知识与力量','{"A":"②④③①","B":"②③④①","C":"④②③①","D":"④③②①"}'::jsonb,'A','','先提出观点②，再讲阅读收获④，接着倡议③，最后总结①。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-025',25,'语文','文言文翻译','单选题','基础','下列文言句子翻译有误的一项是（　）原句：三人行，必有我师焉。','{"A":"几个人一起走路，其中一定有可以做我老师的人。","B":"三个人走路，必须有我的老师。","C":"多人同行，总能找到值得我学习的人。","D":"几个人一同出行，其中必定有能当我老师的人。"}'::jsonb,'B','','B项翻译生硬、绝对化，不符合文言原意。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-026',26,'语文','字音字形','单选题','基础','下列加点字的注音有误的一项是（　）','{"A":"追溯（sù）　匿名（nì）　脍炙人口（kuài）","B":"庇护（pì）　繁衍（yǎn）　相形见绌（chù）","C":"污秽（huì）　绮丽（qǐ）　风雪载途（zài）","D":"缄默（jiān）　吞噬（shì）　面面相觑（qù）"}'::jsonb,'B','','B项“庇”应读bì。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-027',27,'语文','字音字形','单选题','基础','下列词语中有错别字的一项是（　）','{"A":"迁徙　和煦　融会贯通","B":"诘责　和煦　再接再厉","C":"颓唐　教诲　郑重其事","D":"渊搏　愧怍　万贯家私"}'::jsonb,'D','','D项“渊搏”应为“渊博”。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-028',28,'语文','词语运用','单选题','基础','依次填入下面横线处的词语，最恰当的一项是（　）我们要______传统文化，______时代精神，______社会责任，______美好家园。','{"A":"传承　弘扬　担负　建设","B":"继承　发扬　承担　建造","C":"传承　发扬　担负　建造","D":"继承　弘扬　承担　建设"}'::jsonb,'A','','传承文化、弘扬精神、担负责任、建设家园。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-029',29,'语文','成语运用','单选题','基础','下列句子中加点成语使用不正确的一项是（　）','{"A":"他对工作一丝不苟，深受大家信赖。","B":"在中考冲刺阶段，同学们精益求精，不断进步。","C":"他上课经常早退，老师批评了好几回，他还是改不了，已经到了无可救药的地步。","D":"大家认为他提出的这条建议很有价值，都随声附和表示赞成。"}'::jsonb,'D','','“随声附和”指没有主见、盲目附和，是贬义词。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-030',30,'语文','病句辨析','单选题','基础','下列句子有语病的一项是（　）','{"A":"江西拥有丰富的红色文化资源，是红色教育的重要基地。","B":"同学们以敬佩的目光注视着和倾听着这位英雄的报告。","C":"良好的心态是考试取得成功的重要因素。","D":"通过开展垃圾分类宣传活动，同学们的环保意识增强了。"}'::jsonb,'B','','“注视着”与“报告”搭配不当，应删去“注视着和”。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-031',31,'语文','标点符号','单选题','基础','下列句子标点使用完全正确的一项是（　）','{"A":"我不知道这件事是谁做的？但我一定会查清楚。","B":"参加这次公益活动的有中学生、大学生、工人、和教师。","C":"鲁迅先生说的：“时间就像海绵里的水，只要愿挤，总还是有的。”","D":"春天，万物复苏，百花齐放；夏天，骄阳似火，绿树成荫。"}'::jsonb,'D','','A项陈述句不用问号；B项删去“和”前顿号；C项冒号多余。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-032',32,'语文','修辞手法','单选题','基础','下列句子运用比喻修辞手法的一项是（　）','{"A":"他好像生病了，脸色很难看。","B":"理想是闹钟，敲碎你的黄金梦。","C":"我仿佛听见鸟儿的欢唱。","D":"他长得很像他的哥哥。"}'::jsonb,'B','','B项把“理想”比作“闹钟”，是比喻；其余为比较、猜测或感觉。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-033',33,'语文','文化常识','单选题','基础','下列文化常识表述正确的一项是（　）','{"A":"农历五月初五是端午节，习俗有吃粽子、赛龙舟、挂艾草。","B":"古人称“令尊”是对自己母亲的谦称。","C":"“而立之年”指四十岁。","D":"古代科举考试中，殿试第一名是榜眼。"}'::jsonb,'A','','“令尊”是对对方父亲的尊称；“而立”指三十岁；殿试第一名为状元。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-034',34,'语文','句式变换','单选题','基础','下列句子句式变换后意思发生改变的一项是（　）','{"A":"原句：他把教室打扫干净了。变句：教室被他打扫干净了。","B":"原句：我们不能浪费时间。变句：我们难道能浪费时间吗？","C":"原句：这场电影很精彩。变句：这场电影不精彩。","D":"原句：我必须完成作业。变句：我不得不完成作业。"}'::jsonb,'C','','C项原句肯定，变换后否定，意思相反。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
insert into public.questions(id,source_no,subject,knowledge_point,type,difficulty,stem,options,answer,answer_text,explanation,source,source_level) values ('JX2026-035',35,'语文','古诗文默写','单选题','基础','下列古诗文默写判断正确的一项是（　）','{"A":"“会当凌绝顶，一览众山小”——杜甫《春望》","B":"“大漠孤烟直，长河落日圆”——王维《使至塞上》","C":"“但愿人长久，千里共婵娟”——李白《水调歌头》","D":"“海内存知己，天涯若比邻”——白居易《送杜少府之任蜀州》"}'::jsonb,'B','','A项出自杜甫《望岳》；C项作者是苏轼；D项作者是王勃。','江西省2026年高职单独招生《文化统考》语文+数学合卷（用户提供PDF）','用户提供试卷') on conflict (id) do update set source_no=excluded.source_no,subject=excluded.subject,knowledge_point=excluded.knowledge_point,type=excluded.type,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,answer_text=excluded.answer_text,explanation=excluded.explanation,source=excluded.source,source_level=excluded.source_level,updated_at=now();
